const $=s=>document.querySelector(s),photos=[{"id":"coast","title":"Water, held still","category":"Landscape","source":"photo-1476514525535-07fb3b4ae5f1","w":1280,"h":854},{"id":"portrait","title":"An unhurried moment","category":"Portrait","source":"photo-1506794778202-cad84cf45f1d","w":1000,"h":1500},{"id":"objects","title":"The shape of ordinary things","category":"Commercial","source":"photo-1493106641515-6b5631de4bb9","w":900,"h":539},{"id":"dunes","title":"Where the light settles","category":"Landscape","source":"photo-1509316785289-025f5b846b35","w":1280,"h":848},{"id":"rail","title":"Between here and there","category":"Personal","source":"photo-1474487548417-781cb71495f3","w":900,"h":531},{"id":"portrait-light","title":"In natural light","category":"Portrait","source":"photo-1438761681033-6461ffad8d80","w":1000,"h":667}];let category='All',limit=4,current=0;const filtered=()=>photos.filter(p=>category==='All'||p.category===category);function render(){const a=filtered();$('#gallery').innerHTML=a.slice(0,limit).map(p=>'<button class="photo" data-photo="'+p.id+'" aria-label="Open '+p.title+'"><img src="'+p.id+'.webp" srcset="'+p.id+'-small.webp 480w, '+p.id+'.webp '+p.w+'w" sizes="(max-width:450px) 100vw, (max-width:850px) 50vw, 33vw" width="'+p.w+'" height="'+p.h+'" loading="lazy" alt="Stock '+p.category.toLowerCase()+' photograph: '+p.title+'"><span class="overlay"><strong>'+p.title+'</strong><small>'+p.category+' / STOCK STUDY</small></span></button>').join('');$('#galleryStatus').textContent=Math.min(limit,a.length)+' of '+a.length+' photographs · '+category;$('#more').hidden=limit>=a.length;document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>show(a.findIndex(p=>p.id===b.dataset.photo)));document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===category))}function show(i){const a=filtered();current=(i+a.length)%a.length;const p=a[current];$('#large').src=p.id+'.webp';$('#large').alt='Stock '+p.category.toLowerCase()+' photograph: '+p.title;$('#large').width=p.w;$('#large').height=p.h;$('#photoTitle').textContent=p.title+' / '+(current+1)+' of '+a.length;$('#info').textContent='Illustrative stock photograph from Unsplash. Source: https://images.unsplash.com/'+p.source+'. Camera, lens and exposure settings not supplied. Display title is editorial, not an original photographer caption.';$('#share').hidden=true;if(!$('#lightbox').open)$('#lightbox').showModal()}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{category=b.dataset.filter;limit=4;render();$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded',false)});$('#more').onclick=()=>{limit+=4;render()};$('#prev').onclick=()=>show(current-1);$('#next').onclick=()=>show(current+1);$('#close').onclick=()=>$('#lightbox').close();$('#infoButton').onclick=()=>{$('#info').hidden=!$('#info').hidden;$('#infoButton').setAttribute('aria-expanded',!$('#info').hidden)};$('#shareButton').onclick=async()=>{const p=filtered()[current],u=new URL(location.href);u.hash='photo='+p.id;$('#shareLink').value=u.href;$('#share').hidden=false;try{await navigator.clipboard.writeText(u.href);$('#shareStatus').textContent='Image link copied. It points to this static page, not an image sale.'}catch{$('#shareStatus').textContent='Link ready above. Select and copy it manually.'}};document.addEventListener('keydown',e=>{if($('#lightbox').open&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();show(current+(e.key==='ArrowRight'?1:-1))}});let touchX=0;$('#large').onpointerdown=e=>touchX=e.clientX;$('#large').onpointerup=e=>{if(Math.abs(e.clientX-touchX)>40)show(current+(e.clientX<touchX?1:-1))};$('#enquiry').onsubmit=e=>{e.preventDefault();$('#status').textContent='Local enquiry prepared. Nothing was sent, saved or booked.'};$('#menu').onclick=()=>$('#menu').setAttribute('aria-expanded',$('#nav').classList.toggle('open'));render();const photo=new URLSearchParams(location.hash.slice(1)).get('photo');if(photo&&photos.some(p=>p.id===photo))show(photos.findIndex(p=>p.id===photo));